<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Canvas Billiards</title>
<style>
  :root {
    color-scheme: dark;
    --wood: #5c2814;
    --gold: #d69a43;
    --felt: #0b704c;
  }
  * { box-sizing: border-box; }
  body {
    margin: 0;
    min-height: 100vh;
    display: grid;
    place-items: center;
    background:
      radial-gradient(circle at 50% 15%, #293442 0%, #111820 48%, #080b0f 100%);
    color: #f5ead6;
    font-family: Georgia, "Times New Roman", serif;
  }
  .game {
    width: min(1000px, 96vw);
    padding: 18px;
    border: 1px solid #73512c;
    border-radius: 16px;
    background: linear-gradient(145deg, #2c2119, #15100d);
    box-shadow: 0 18px 60px #000b, inset 0 1px 0 #ffffff18;
  }
  header {
    display: flex;
    gap: 14px;
    justify-content: space-between;
    align-items: center;
    margin: 0 2px 13px;
  }
  h1 {
    margin: 0;
    letter-spacing: .08em;
    font-size: clamp(1.05rem, 3vw, 1.55rem);
    color: #f2c776;
    text-shadow: 0 2px 2px #000;
  }
  button {
    cursor: pointer;
    border: 1px solid #e0ac54;
    border-radius: 7px;
    padding: 8px 14px;
    color: #2b1607;
    font: bold 14px Georgia, serif;
    background: linear-gradient(#ffe1a0, #c98c34);
    box-shadow: inset 0 1px #fff8, 0 2px 4px #0008;
  }
  button:hover { filter: brightness(1.1); }
  button:active { transform: translateY(1px); }
  canvas {
    display: block;
    width: 100%;
    height: auto;
    border-radius: 10px;
    background: #3c1c0e;
    box-shadow: 0 8px 20px #000a;
    touch-action: none;
  }
  .instructions {
    margin: 12px 4px 0;
    min-height: 1.25em;
    text-align: center;
    font-size: clamp(.86rem, 2.4vw, 1rem);
    color: #e8d9bd;
  }
  .instructions b { color: #ffd57d; }
</style>
</head>
<body>
<div class="game">
  <header>
    <h1>CANVAS BILLIARDS</h1>
    <button id="rack" type="button">Reset / Rack</button>
  </header>
  <canvas id="table" width="960" height="510" aria-label="Playable billiards table"></canvas>
  <div class="instructions" id="instructions">
    <b>How to shoot:</b> Press the white cue ball, drag back to aim and set power, then release.
  </div>
</div>

<script>
(() => {
  "use strict";

  const canvas = document.getElementById("table");
  const ctx = canvas.getContext("2d");
  const message = document.getElementById("instructions");

  const W = 900, H = 450, R = 12;
  const RAIL = 30;
  const POCKET_R = 21;
  const FRICTION = 92;              // pixels/sec²
  const WALL_RESTITUTION = 0.93;
  const STOP_SPEED = 1.5;
  const pockets = [
    { x: 0,     y: 0 }, { x: W / 2, y: 0 }, { x: W, y: 0 },
    { x: 0,     y: H }, { x: W / 2, y: H }, { x: W, y: H }
  ];
  const colors = [
    "#ffffff", "#e8b72d", "#276ed0", "#d52d29", "#7c3787",
    "#e76d25", "#18884c", "#742524", "#151515", "#e8b72d",
    "#276ed0", "#d52d29", "#7c3787", "#e76d25", "#18884c", "#742524"
  ];

  let balls = [];
  let running = true;
  let frameHandle = 0;
  let previousTime = 0;
  let drag = null;

  function finite(v, fallback) {
    return Number.isFinite(v) ? v : fallback;
  }

  function reset(inputBalls) {
    balls = (Array.isArray(inputBalls) ? inputBalls : []).map((b, i) => ({
      x: finite(b.x, W / 2),
      y: finite(b.y, H / 2),
      vx: finite(b.vx, 0),
      vy: finite(b.vy, 0),
      cue: b.cue === true,
      potted: false,
      color: b.cue === true ? "#ffffff" : colors[(i % (colors.length - 1)) + 1]
    }));
    draw();
  }

  function state() {
    return balls.map(b => ({
      x: b.x, y: b.y, vx: b.vx, vy: b.vy,
      potted: b.potted, cue: b.cue
    }));
  }

  function cueBall() {
    return balls.find(b => b.cue && !b.potted) || null;
  }

  function shoot(vx, vy) {
    const cue = cueBall();
    if (!cue) return;
    cue.vx = finite(vx, 0);
    cue.vy = finite(vy, 0);
    draw();
  }

  function potCheck(b) {
    for (const p of pockets) {
      const dx = b.x - p.x, dy = b.y - p.y;
      if (dx * dx + dy * dy <= POCKET_R * POCKET_R) {
        b.potted = true;
        b.vx = 0;
        b.vy = 0;
        return true;
      }
    }
    return false;
  }

  function cushion(b) {
    if (b.x < R) {
      b.x = R;
      if (b.vx < 0) b.vx = -b.vx * WALL_RESTITUTION;
    } else if (b.x > W - R) {
      b.x = W - R;
      if (b.vx > 0) b.vx = -b.vx * WALL_RESTITUTION;
    }
    if (b.y < R) {
      b.y = R;
      if (b.vy < 0) b.vy = -b.vy * WALL_RESTITUTION;
    } else if (b.y > H - R) {
      b.y = H - R;
      if (b.vy > 0) b.vy = -b.vy * WALL_RESTITUTION;
    }
  }

  function collide(a, b, ai, bi) {
    let dx = b.x - a.x;
    let dy = b.y - a.y;
    let d2 = dx * dx + dy * dy;
    const minD = 2 * R;
    if (d2 >= minD * minD) return;

    let d = Math.sqrt(d2);
    let nx, ny;
    if (d < 0.000001) {
      // Fixed, index-based normal avoids nondeterminism for exactly overlapping balls.
      const angle = ((ai * 37 + bi * 91) % 360) * Math.PI / 180;
      nx = Math.cos(angle);
      ny = Math.sin(angle);
      d = 0;
    } else {
      nx = dx / d;
      ny = dy / d;
    }

    // Separate the balls before applying the velocity impulse.
    const overlap = minD - d;
    const separation = overlap * 0.5 + 0.00001;
    a.x -= nx * separation;
    a.y -= ny * separation;
    b.x += nx * separation;
    b.y += ny * separation;

    // Perfectly elastic equal-mass impulse along the centre line.
    const relativeNormalSpeed = (b.vx - a.vx) * nx + (b.vy - a.vy) * ny;
    if (relativeNormalSpeed < 0) {
      const impulse = -relativeNormalSpeed; // restitution = 1, masses = 1
      a.vx -= impulse * nx;
      a.vy -= impulse * ny;
      b.vx += impulse * nx;
      b.vy += impulse * ny;
    }
  }

  function microStep(dt) {
    for (const b of balls) {
      if (b.potted) continue;

      b.x += b.vx * dt;
      b.y += b.vy * dt;

      const speed = Math.hypot(b.vx, b.vy);
      if (speed > 0) {
        const newSpeed = Math.max(0, speed - FRICTION * dt);
        if (newSpeed === 0 || newSpeed < STOP_SPEED) {
          b.vx = 0;
          b.vy = 0;
        } else {
          const scale = newSpeed / speed;
          b.vx *= scale;
          b.vy *= scale;
        }
      }

      if (!potCheck(b)) cushion(b);
    }

    // Several passes make simultaneous contacts stable without changing the fixed order.
    for (let pass = 0; pass < 3; pass++) {
      for (let i = 0; i < balls.length; i++) {
        const a = balls[i];
        if (a.potted) continue;
        for (let j = i + 1; j < balls.length; j++) {
          const b = balls[j];
          if (!b.potted) collide(a, b, i, j);
        }
      }
      for (const b of balls) {
        if (!b.potted && !potCheck(b)) cushion(b);
      }
    }
  }

  function step(dt) {
    dt = finite(dt, 0);
    if (dt <= 0) {
      draw();
      return;
    }
    // Small fixed-size segments prevent balls tunneling through each other.
    const count = Math.max(1, Math.ceil(dt / (1 / 240)));
    const slice = dt / count;
    for (let i = 0; i < count; i++) microStep(slice);
    draw();
  }

  function allStill() {
    return balls.every(b => b.potted || Math.hypot(b.vx, b.vy) < STOP_SPEED);
  }

  function lineToEdge(x, y, dx, dy) {
    let t = Infinity;
    if (dx > 0) t = Math.min(t, (W - R - x) / dx);
    if (dx < 0) t = Math.min(t, (R - x) / dx);
    if (dy > 0) t = Math.min(t, (H - R - y) / dy);
    if (dy < 0) t = Math.min(t, (R - y) / dy);
    return Math.max(0, t);
  }

  function drawBall(b, index) {
    const x = RAIL + b.x, y = RAIL + b.y;
    ctx.save();
    ctx.beginPath();
    ctx.arc(x + 2, y + 3, R, 0, Math.PI * 2);
    ctx.fillStyle = "#0008";
    ctx.fill();

    const g = ctx.createRadialGradient(x - R * .35, y - R * .42, 1, x, y, R * 1.2);
    g.addColorStop(0, b.cue ? "#ffffff" : "#ffffffaa");
    g.addColorStop(.22, b.color);
    g.addColorStop(1, b.cue ? "#bfc8ca" : "#111");
    ctx.beginPath();
    ctx.arc(x, y, R, 0, Math.PI * 2);
    ctx.fillStyle = g;
    ctx.fill();
    ctx.lineWidth = 1;
    ctx.strokeStyle = "#0009";
    ctx.stroke();

    if (!b.cue && index > 0) {
      ctx.beginPath();
      ctx.arc(x, y, R * .37, 0, Math.PI * 2);
      ctx.fillStyle = "#f4ecd9";
      ctx.fill();
      ctx.fillStyle = "#1d1915";
      ctx.font = "bold 8px Arial";
      ctx.textAlign = "center";
      ctx.textBaseline = "middle";
      ctx.fillText(String(((index - 1) % 15) + 1), x, y + .5);
    }
    ctx.restore();
  }

  function draw() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    ctx.fillStyle = "#321609";
    ctx.fillRect(0, 0, canvas.width, canvas.height);
    ctx.fillStyle = "#7b3e19";
    ctx.fillRect(8, 8, canvas.width - 16, canvas.height - 16);
    ctx.strokeStyle = "#c18a42";
    ctx.lineWidth = 3;
    ctx.strokeRect(13, 13, canvas.width - 26, canvas.height - 26);

    ctx.fillStyle = "#083d2b";
    ctx.fillRect(RAIL - 5, RAIL - 5, W + 10, H + 10);
    const felt = ctx.createLinearGradient(RAIL, RAIL, RAIL + W, RAIL + H);
    felt.addColorStop(0, "#117b58");
    felt.addColorStop(.55, "#0c6849");
    felt.addColorStop(1, "#075039");
    ctx.fillStyle = felt;
    ctx.fillRect(RAIL, RAIL, W, H);

    ctx.strokeStyle = "#49a37c44";
    ctx.lineWidth = 1;
    for (let x = RAIL + 40; x < RAIL + W; x += 40) {
      ctx.beginPath();
      ctx.moveTo(x, RAIL);
      ctx.lineTo(x, RAIL + H);
      ctx.stroke();
    }

    for (const p of pockets) {
      const px = RAIL + p.x, py = RAIL + p.y;
      ctx.beginPath();
      ctx.arc(px, py, POCKET_R + 4, 0, Math.PI * 2);
      ctx.fillStyle = "#1a0b06";
      ctx.fill();
      ctx.beginPath();
      ctx.arc(px, py, POCKET_R - 2, 0, Math.PI * 2);
      ctx.fillStyle = "#030303";
      ctx.fill();
    }

    const cue = cueBall();
    if (drag && cue && allStill()) {
      const dx = cue.x - drag.x, dy = cue.y - drag.y;
      const length = Math.hypot(dx, dy);
      if (length > 1) {
        const nx = dx / length, ny = dy / length;
        const endT = lineToEdge(cue.x, cue.y, nx, ny);
        ctx.save();
        ctx.setLineDash([8, 7]);
        ctx.lineWidth = 1.5;
        ctx.strokeStyle = "#f7e5a8cc";
        ctx.beginPath();
        ctx.moveTo(RAIL + cue.x, RAIL + cue.y);
        ctx.lineTo(RAIL + cue.x + nx * endT, RAIL + cue.y + ny * endT);
        ctx.stroke();

        const back = Math.min(90, length);
        ctx.setLineDash([]);
        ctx.lineWidth = 5;
        ctx.strokeStyle = "#d7a25b";
        ctx.beginPath();
        ctx.moveTo(RAIL + cue.x - nx * (R + 4), RAIL + cue.y - ny * (R + 4));
        ctx.lineTo(RAIL + cue.x - nx * (R + back), RAIL + cue.y - ny * (R + back));
        ctx.stroke();
        ctx.restore();
      }
    }

    balls.forEach((b, i) => { if (!b.potted) drawBall(b, i); });

    if (balls.some(b => b.cue && b.potted)) {
      message.innerHTML = "<b>Cue ball potted.</b> Use Reset / Rack to begin again.";
    } else if (allStill()) {
      message.innerHTML = "<b>How to shoot:</b> Press the white cue ball, drag back to aim and set power, then release.";
    } else {
      message.innerHTML = "<b>Balls are rolling.</b> Wait for them to settle before your next shot.";
    }
  }

  function canvasPoint(event) {
    const rect = canvas.getBoundingClientRect();
    return {
      x: (event.clientX - rect.left) * canvas.width / rect.width - RAIL,
      y: (event.clientY - rect.top) * canvas.height / rect.height - RAIL
    };
  }

  canvas.addEventListener("pointerdown", event => {
    const p = canvasPoint(event);
    const cue = cueBall();
    if (!cue || !allStill()) return;
    const dx = p.x - cue.x, dy = p.y - cue.y;
    if (dx * dx + dy * dy <= (R * 2.1) * (R * 2.1)) {
      drag = p;
      canvas.setPointerCapture(event.pointerId);
      draw();
      event.preventDefault();
    }
  });

  canvas.addEventListener("pointermove", event => {
    if (!drag) return;
    drag = canvasPoint(event);
    draw();
  });

  function releaseShot(event) {
    if (!drag) return;
    const cue = cueBall();
    const p = canvasPoint(event);
    if (cue && allStill()) {
      const dx = cue.x - p.x;
      const dy = cue.y - p.y;
      const length = Math.hypot(dx, dy);
      if (length > 3) {
        const capped = Math.min(length, 240);
        const power = capped * 4.2;
        shoot(dx / length * power, dy / length * power);
      }
    }
    drag = null;
    draw();
  }

  canvas.addEventListener("pointerup", releaseShot);
  canvas.addEventListener("pointercancel", () => { drag = null; draw(); });

  function rack() {
    const layout = [{ x: 190, y: H / 2, vx: 0, vy: 0, cue: true }];
    const apexX = 655;
    for (let row = 0; row < 5; row++) {
      for (let n = 0; n <= row; n++) {
        layout.push({
          x: apexX + row * Math.sqrt(3) * R,
          y: H / 2 - row * R + n * R * 2,
          vx: 0, vy: 0, cue: false
        });
      }
    }
    reset(layout);
  }

  document.getElementById("rack").addEventListener("click", rack);

  function animate(now) {
    if (!running) return;
    if (previousTime) {
      // Visual animation uses bounded elapsed time; direct sim.step remains exact.
      const dt = Math.min(.04, (now - previousTime) / 1000);
      step(dt);
    }
    previousTime = now;
    frameHandle = requestAnimationFrame(animate);
  }

  function pause() {
    running = false;
    if (frameHandle) cancelAnimationFrame(frameHandle);
    frameHandle = 0;
    previousTime = 0;
  }

  function resume() {
    if (running) return;
    running = true;
    previousTime = 0;
    frameHandle = requestAnimationFrame(animate);
  }

  window.sim = {
    W: W,
    H: H,
    R: R,
    reset: reset,
    step: step,
    state: state,
    shoot: shoot,
    pause: pause,
    resume: resume
  };

  rack();
  frameHandle = requestAnimationFrame(animate);
})();
</script>
</body>
</html>
